package main

import (
	"context"
	"log/slog"
	"net/url"

	"github.com/quay/claircore"
	"github.com/quay/claircore/indexer"
)

var _ indexer.PackageScanner = (*MappedPackageScanner)(nil)

// MappedPackageScanner enriches RHEL package repository hints using an
// authoritative package-name mapping.
type MappedPackageScanner struct {
	inner  indexer.PackageScanner
	byName map[string]string
}

func NewMappedPackageScanner(inner indexer.PackageScanner, byName map[string]string) *MappedPackageScanner {
	return &MappedPackageScanner{inner: inner, byName: byName}
}

func (s *MappedPackageScanner) Name() string {
	return s.inner.Name()
}

func (s *MappedPackageScanner) Version() string {
	return s.inner.Version()
}

func (s *MappedPackageScanner) Kind() string {
	return s.inner.Kind()
}

func (s *MappedPackageScanner) Scan(ctx context.Context, layer *claircore.Layer) ([]*claircore.Package, error) {
	packages, err := s.inner.Scan(ctx, layer)
	if err != nil {
		return packages, err
	}

	out := make([]*claircore.Package, 0, len(packages))
	for _, pkg := range packages {
		if pkg == nil {
			slog.WarnContext(ctx, "omitting nil package returned by scanner")
			continue
		}

		originalHint := pkg.RepositoryHint
		hint, err := url.ParseQuery(originalHint)
		if err != nil {
			slog.WarnContext(ctx, "unable to parse package repository hint; using broad repository association", "package", pkg.Name, "hint", originalHint, "reason", err)
			pkg.RepositoryHint = ""
			out = append(out, pkg)
			continue
		}

		repoid, mapped := s.byName[pkg.Name]
		switch {
		case mapped && repoid != "":
			hint.Set("repoid", repoid)
			pkg.RepositoryHint = hint.Encode()
		case !mapped && hint.Get("repoid") != "":
			slog.WarnContext(ctx, "found unmapped package; using broad repository association", "package", pkg.Name, "hint", originalHint, "repoid", hint.Get("repoid"))
			hint.Del("repoid")
			pkg.RepositoryHint = hint.Encode()
		}

		out = append(out, pkg)
	}

	return out, nil
}

